<?php
/**
 * Proof — the end-to-end gate of design §10, Phase 5, on a SCRATCH installation (the live proof is the same story told by people, docs/phase5-runbook.md): an invoice is issued, sent through MaluMail, viewed
 * on its link, claimed, confirmed into a receipt and deposited; the deposit matches one bank line; a bill is attached, approved and paid in a run; the kernel's closed month becomes bills that agree with the
 * statement; the month is reconciled and closed; the trial balance balances, the balance sheet holds and the cash flow statement explains the change in cash; the command bar's "who owes us over 60 days".
 */
require dirname(__DIR__) . '/phase4/lib.php';
$owner = as_member(1); $bea = as_member(27); $carl = as_member(28);
ensure_year($owner); $fx = ap_fixture(); $bank = $fx['bank']; $tax = $fx['tax'];
$acme = mk_customer('SMOKE E2E Acme'); $beta = mk_customer('SMOKE E2E Beta'); $host = mk_vendor('SMOKE E2E Hosting', ['pay_method' => 'ach']);
echo "1. The books open\n";
$capital = post_as_carl('2026-09-01', [line('1010', '10000.00', '0.00'), line('3000', '0.00', '10000.00')], 'SMOKE E2E owner capital');
$l_cap = bank_line_row($bank, '2026-09-01', '10000.00', 'E2E CAPITAL IN', 'E2E-CAP');
ok($capital > 0 && (string) one('SELECT status FROM journal_entries WHERE id = :i', ['i' => $capital]) === 'posted', 'the owner\'s capital is posted: 10,000.00 into the bank account');
echo "2. An invoice: issued, sent, viewed, claimed, received, deposited\n";
$inv = mk_invoice($acme, [['Consulting', '2', '500.00', $tax]], ['issue_date' => '2026-09-03', 'due_date' => '2026-10-03']);
$r = issue($inv);
ok(($r['_code'] ?? 0) === 200 && preg_match('/^INV-\d{5}$/', (string) $r['number']) === 1 && inv_row($inv)['total'] === '1082.50', 'issued: numbered ' . $r['number'] . ', 1,082.50 with the tax; the entry posted');
$mails = count(mail_log());
[$c, $b] = act($bea, '/invoices/send.php', ['invoice' => $inv]);
worker(['--only=send']);
$mail = array_values(array_filter(array_slice(mail_log(), $mails), fn ($m) => str_contains((string) $m['to'], 'smokee2eacme')));
$mail = end($mail) ?: [];
preg_match('#/i/([a-f0-9]{48})#', (string) ($mail['text'] ?? ''), $m);
$tok = $m[1] ?? '';
ok($c === 200 && $tok !== '' && str_contains((string) ($mail['subject'] ?? ''), $r['number']), 'sent: MaluMail received the mail with the secure link in its body');
$jar = jar(); $page = req('GET', '/i/' . $tok, ['jar' => $jar]);
ok($page['code'] === 200 && str_contains($page['body'], $r['number']) && inv_row($inv)['status'] === 'viewed', 'the customer opens the link: the invoice shows and its status is viewed');
$csrf = preg_match('/name="csrf_token" value="([^"]+)"/', $page['body'], $mm) ? $mm[1] : '';
$post = req('POST', '/i/' . $tok . '/claim', ['jar' => $jar, 'form' => ['csrf_token' => $csrf, 'claimed_on' => '2026-09-07', 'method' => 'transfer', 'reference' => 'E2E-TRF', 'amount' => '1082.50']]);
$claim = (int) one('SELECT id FROM receipt_claims WHERE invoice_id = :i ORDER BY id DESC LIMIT 1', ['i' => $inv]);
ok($post['code'] === 200 && $claim > 0, 'the customer says they paid (a claim, 1,082.50)');
[$c, $b] = act($bea, '/receipts/claim-confirm.php', ['claim' => $claim]);
$rcpt = (int) one('SELECT receipt_id FROM receipt_claims WHERE id = :c', ['c' => $claim]);
ok($c === 200 && $rcpt > 0 && inv_row($inv)['status'] === 'paid' && inv_row($inv)['balance_due'] === '0.00', 'the Bookkeeper confirms it: a receipt, applied, the invoice paid');
[$c, $b] = act($bea, '/deposits/save.php', ['bank_account' => $bank, 'deposit_date' => '2026-09-08', 'receipts' => [$rcpt]]);
$dep = (int) ($b['record_id'] ?? 0);
[$c2] = act($bea, '/deposits/record.php', ['deposit' => $dep]);
ok($c === 200 && $c2 === 200 && one('SELECT status FROM deposits WHERE id = :d', ['d' => $dep]) === 'recorded', 'deposited: the receipt leaves Undeposited funds for the bank (a recorded deposit)');
$l_dep = bank_line_row($bank, '2026-09-08', '1082.50', 'E2E DEPOSIT', 'E2E-DEP');
$cand = tdata(27, 'match_candidates', ['bank_transaction_id' => $l_dep]);
ok($cand['count'] === 1 && $cand['candidates'][0]['item_type'] === 'deposit' && $cand['candidates'][0]['item_id'] === $dep, 'the MCP tool offers exactly one candidate for the bank line: the deposit');
[$c] = act($bea, '/cash/match.php', ['bank_line' => $l_dep, 'item_type' => 'deposit', 'item' => $dep]);
[$c3] = act($bea, '/cash/match.php', ['bank_line' => $l_cap, 'item_type' => 'journal_entry', 'item' => $capital]);
ok($c === 200 && $c3 === 200 && line_status($l_dep) === 'matched' && line_status($l_cap) === 'matched', 'the deposit matches its bank line, and so does the capital');
echo "3. A bill: attached, approved, paid in a run\n";
[$c, $b, $raw] = act_upload($bea, '/bills/save.php', ['vendor' => $host, 'vendor_ref' => 'E2E-H-1', 'bill_date' => '2026-09-10', 'due_date' => '2026-09-25', 'lines' => json_encode([['description' => 'Hosting September', 'quantity' => '1', 'unit_price' => '400.00', 'expense_account' => '6200']])], ['document' => [tmp_pdf('E2E-hosting.pdf'), 'invoice.pdf']]);
$bill = (int) ($b['record_id'] ?? 0);
ok($bill > 0 && (int) one("SELECT count(*) FROM attachments WHERE record_type = 'bill' AND record_id = :b", ['b' => $bill]) === 1, 'the vendor\'s invoice is entered with its document attached');
[$c] = act($carl, '/bills/approve.php', ['bill' => $bill]);
ok($c === 200 && bill_row($bill)['status'] === 'approved', 'the Controller approves it: the entry posts against payables');
[$c, $b] = act($bea, '/payment-runs/save.php', ['bank_account' => $bank, 'pay_date' => '2026-09-20', 'bills' => [$bill]]);
$run = (int) ($b['record_id'] ?? 0);
[$ca] = act($carl, '/payment-runs/approve.php', ['payment_run' => $run]);
[$cr] = act($bea, '/payment-runs/record.php', ['payment_run' => $run, 'pay_date' => '2026-09-20']);
ok($run > 0 && $ca === 200 && $cr === 200 && bill_row($bill)['status'] === 'paid', 'a payment run is made, approved by the Controller and recorded: the bill is paid');
$pay = (int) one('SELECT id FROM payments WHERE payment_run_id = :r ORDER BY id LIMIT 1', ['r' => $run]);
$l_pay = bank_line_row($bank, '2026-09-20', '-400.00', 'E2E HOSTING ACH', 'E2E-PAY');
[$c] = act($bea, '/cash/match.php', ['bank_line' => $l_pay, 'item_type' => 'payment', 'item' => $pay]);
ok($c === 200 && line_status($l_pay) === 'matched', 'the payment matches its bank line');
echo "4. The kernel's closed month becomes bills that agree\n";
$doc = ai_doc('2026-09', 'closed', [ai_line('anthropic', 'claude-sonnet-5-5', 'Accounting', 'Sasha', 120, 0, '12.3456'), ai_line('anthropic', 'claude-sonnet-5-5', 'IT', 'Sysadmin', 80, 2, '7.6549', '2 late calls'), ai_line('openai', 'gpt-5', 'Front Office', 'Seamus', 30, 0, '3.0000')]);
ledger_state(['2026-09' => $doc]);
act($bea, '/ap/ai/pull.php', ['period' => '2026-09']);
$S = stmt_id('2026-09');
[$c, $b] = act($bea, '/ap/ai/import.php', ['ai_statement' => $S]);
$ai = q('SELECT bill_id FROM ai_statement_bills WHERE statement_id = :s', ['s' => $S]);
foreach ($ai as $x) { act($carl, '/bills/approve.php', ['bill' => (int) $x['bill_id']]); }
[$c2, $b2] = act($bea, '/ap/ai/check.php', ['ai_statement' => $S]);
ok($c === 200 && count($ai) === 2 && ($b2['verdict'] ?? '') === 'agrees', 'the closed month is imported as one bill per provider (two), approved, and the check agrees with the statement');
echo "5. Reconciled and closed\n";
$balance = number_format(10000 + 1082.50 - 400, 2, '.', '');
[$c, $b] = act($bea, '/cash/reconcile-start.php', ['bank_account' => $bank, 'statement_date' => '2026-09-30', 'statement_balance' => $balance]);
$rec = (int) ($b['record_id'] ?? 0);
[$c2, $b2] = act($carl, '/cash/reconcile-complete.php', ['reconciliation' => $rec, 'note' => 'SMOKE E2E September']);
ok($rec > 0 && $c2 === 200 && one('SELECT status FROM bank_reconciliations WHERE id = :r', ['r' => $rec]) === 'completed', "September's bank statement ($balance) reconciles to a zero difference and the Controller completes it" . ($c2 === 200 ? '' : ' — ' . msg($b2)));
$pid = period_id('2026-09');
[$c, $b] = act($carl, '/periods/close.php', ['period' => $pid]);
ok($c === 200 && one('SELECT status FROM fiscal_periods WHERE id = :p', ['p' => $pid]) === 'closed', 'September is closed' . ($c === 200 ? '' : ' — ' . msg($b)));
[$c, $b] = act($bea, '/journal/save.php', ['entry_date' => '2026-09-29', 'memo' => 'SMOKE E2E late', 'lines' => json_encode([line('6200', '1.00', '0.00'), line('1010', '0.00', '1.00')])]);
[$pc, $pb] = act($carl, '/journal/post.php', ['entry' => (int) ($b['record_id'] ?? 0)]);
ok($pc === 422 && str_contains(strtolower(msg($pb)), 'closed'), 'nothing more can be posted into it: ' . msg($pb));
echo "6. The statements\n";
$tb = tdata(28, 'trial_balance', ['as_of' => '2026-09-30']);
ok($tb['balanced'] === true && count($tb['rows']) >= 6, 'the trial balance balances (' . $tb['total_debit'] . ' = ' . $tb['total_credit'] . ')');
$bs = tdata(28, 'balance_sheet', ['as_of' => '2026-09-30']);
ok((float) $bs['check']['difference'] === 0.0, 'the balance sheet holds: assets = liabilities + equity (' . $bs['check']['assets'] . ')');
$cf = tdata(28, 'cash_flow', ['from' => '2026-09-01', 'to' => '2026-09-30']);
$sum = []; foreach ($cf['sections'] as $s) { foreach ($s['lines'] as $l) { $sum[$l['label']] = $l['amount']; } }
$delta = (float) val_as(28, "SELECT gl_account_balance(:a, DATE '2026-09-30') - gl_account_balance(:a, DATE '2026-08-31')", ['a' => account_id('1010')]);
ok(same_money($sum['Net change in cash'] ?? 'x', $delta) && same_money($sum['Cash at end'] ?? 'x', 10682.50) && same_money($sum['Cash at start'] ?? 'x', 0) && same_money($sum['Check: end − start − net change (must be zero)'] ?? 'x', 0), 'the cash flow statement explains the change in cash: ' . ($sum['Net change in cash'] ?? '?') . ' = the bank account\'s movement; start 0.00, end 10,682.50, check 0.00');
ok(abs((float) $sum['Net income'] - (float) val_as(28, "SELECT gl_net_income('2026-09-01', '2026-09-30')")) < 0.005, 'and it starts from the same net income as the profit and loss');
echo "7. The command bar: who owes us over 60 days\n";
$old = mk_invoice($beta, [['Old work', '1', '750.00']], ['issue_date' => '2026-06-01', 'due_date' => '2026-06-30']); issue($old);
$ag = tdata(27, 'ar_aging', ['as_of' => '2026-10-05']);
$beta_row = array_values(array_filter($ag['customers'], fn ($x) => $x['customer_id'] === $beta))[0] ?? [];
ok(same_money($beta_row['days_over_90'] ?? 0, '750.00') && !array_filter($ag['customers'], fn ($x) => $x['customer_id'] === $acme), 'ar_aging: Beta owes 750.00 over 90 days; Acme, who paid, is not listed');
$chat = req('POST', '/assistant/ask.php', ['jar' => $bea, 'form' => ['utterance' => 'who owes us over 60 days', 'screen' => 'home', 'csrf_token' => csrf_of(req('GET', '/', ['jar' => $bea])['body'])]]);
ok(in_array($chat['code'], [200, 503], true), 'the command bar posts the question through the kernel\'s chat endpoint (the fake kernel answers; the real expert reads ar_aging)');
finish();
